package com.smartmart.wishlist.service; import com.smartmart.common.exception.*; import com.smartmart.inventory.repository.InventoryRepository; import com.smartmart.product.repository.ProductRepository; import com.smartmart.user.entity.User; import com.smartmart.wishlist.dto.WishlistResponse; import com.smartmart.wishlist.entity.Wishlist; import com.smartmart.wishlist.repository.WishlistRepository; import lombok.*; import org.springframework.stereotype.*; import org.springframework.transaction.annotation.*; import java.math.BigDecimal; import java.util.*;
@Service @RequiredArgsConstructor public class WishlistService {private final WishlistRepository repo;private final ProductRepository products; private final InventoryRepository inventory; @Transactional public void add(User u,Long product){if(repo.existsByUserIdAndProductId(u.getId(),product))throw BusinessException.conflict("Product is already in wishlist");repo.save(Wishlist.builder().user(u).product(products.findById(product).orElseThrow(()->BusinessException.notFound("Product not found"))).build());} @Transactional(readOnly=true) public List<WishlistResponse> list(User u){return repo.findByUserIdOrderByCreatedAtDesc(u.getId()).stream().map(w->{var p=w.getProduct();var i=inventory.findByProductId(p.getId()).orElse(null);int quantity=i==null?0:i.getQuantity();String status=quantity==0?"OUT_OF_STOCK":quantity<=i.getReorderLevel()?"LOW_STOCK":"AVAILABLE";return WishlistResponse.builder().id(w.getId()).productId(p.getId()).name(p.getName()).brand(p.getBrand()).category(p.getCategory()).price(p.getPrice()).aisle(p.getAisle()).shelf(p.getShelf()).availableQuantity(quantity).discountPercentage(i==null?BigDecimal.ZERO:Optional.ofNullable(i.getDiscountPercentage()).orElse(BigDecimal.ZERO)).availabilityStatus(status).createdAt(w.getCreatedAt()).build();}).toList();} @Transactional public void remove(User u,Long p){if(!repo.existsByUserIdAndProductId(u.getId(),p))throw BusinessException.notFound("Wishlist entry not found");repo.deleteByUserIdAndProductId(u.getId(),p);}}
